import json,itertools,sys
from fractions import Fraction as Fr
pl=json.load(open(sys.argv[1] if len(sys.argv)>1 else '/app/planning.json')); ex=pl['execution']
an=json.load(open(sys.argv[2] if len(sys.argv)>2 else '/app/submission/analysis.json'))
H=ex['horizon']; order=pl['target_order']
cands=[t for t in ex['candidates'] if an['targets'][t]['rollout_eligible']]
F=lambda x: Fr(repr(x)) if isinstance(x,float) else Fr(x)
err={t:F(an['targets'][t]['errors']) for t in order}
R={t:err[t]*F(pl['targets'][t]['risk_weight']) for t in order}
opts=list(range(H))+[None]
def jobs_of(t,s1,s2):
    J=[]
    if s1 is not None:
        d=ex['durations'][t][0]; w=ex['warmups'][t][0]; J.append((t,1,s1,s1+d,s1+d+w))
    if s2 is not None:
        d=ex['durations'][t][1]; w=ex['warmups'][t][1]; J.append((t,2,s2,s2+d,s2+d+w))
    return J
res={}
for combo in itertools.product(*[[(a,b) for a in opts for b in opts if not (a is None and b is not None)] for t in cands]):
    J=[]
    for t,(a,b) in zip(cands,combo): J+=jobs_of(t,a,b)
    if len(J)>ex['max_jobs']: continue
    ok=True
    for j in J:
        if j[4]>H: ok=False
        if any(s in ex['blackouts'].get(j[0],[]) for s in range(j[2],j[3])): ok=False
    if not ok: continue
    byt={}
    for j in J: byt.setdefault(j[0],{})[j[1]]=j
    for t,d in byt.items():
        if 2 in d and d[2][2]<d[1][4]: ok=False
    for s in range(H):
        if sum(1 for j in J if j[2]<=s<j[3])>ex['crews'][s]: ok=False
    for a,b in itertools.combinations(J,2):
        if pl['targets'][a[0]]['region']==pl['targets'][b[0]]['region']:
            if not (a[3]+ex['region_gap']<=b[2] or b[3]+ex['region_gap']<=a[2]): ok=False
    for dp in ex['dependencies']:
        if dp['target'] in byt and dp['tier'] in byt[dp['target']]:
            st=byt[dp['target']][dp['tier']][2]
            pr=byt.get(dp['requires'],{}).get(dp['requires_tier'])
            if pr is None or pr[4]>st: ok=False
    if not ok: continue
    tiers={t:max(byt.get(t,{0:0}).keys()) for t in order}
    cr=sum(F(pl['targets'][t]['cost'][tiers[t]]) for t in order); pw=sum(F(pl['targets'][t]['power'][tiers[t]]) for t in order)
    act={pl['targets'][t]['region'] for t in order if tiers[t]}
    cr+=sum(F(pl['regions'][r]['activation_cost']) for r in act)
    if cr>pl['credit_budget'] or pw>pl['power_budget'] or len(act)>pl['max_active_regions']: continue
    if any(sum(tiers[t] for t in order if pl['targets'][t]['region']==r)>pl['regions'][r]['max_blocks'] for r in pl['regions']): continue
    if any(tiers[t] and pl['regions'][pl['targets'][t]['region']]['frozen'] for t in order): continue
    def eff(t,s):
        if any(j[0]==t and j[2]<=s<j[3] for j in J): return 0
        return max([j[1] for j in J if j[0]==t and j[4]<=s]+[0])
    nets=[]
    for c in ex['cases']:
        n=Fr(0)
        for s in range(H):
            for t in order:
