    cr=sum(F(pl['targets'][t]['cost'][tiers[t]]) for t in order); pw=sum(F(pl['targets'][t]['power'][tiers[t]]) for t in order)
    act={pl['targets'][t]['region'] for t in order if tiers[t]}
    cr+=sum(F(pl['regions'][r]['activation_cost']) for r in act)
    if cr>pl['credit_budget'] or pw>pl['power_budget'] or len(act)>pl['max_active_regions']: continue
    if any(sum(tiers[t] for t in order if pl['targets'][t]['region']==r)>pl['regions'][r]['max_blocks'] for r in pl['regions']): continue
    if any(tiers[t] and pl['regions'][pl['targets'][t]['region']]['frozen'] for t in order): continue
    def eff(t,s):
        if any(j[0]==t and j[2]<=s<j[3] for j in J): return 0
        return max([j[1] for j in J if j[0]==t and j[4]<=s]+[0])
    nets=[]
    for c in ex['cases']:
        n=Fr(0)
        for s in range(H):
            for t in order:
                e=F(c['exposure'][t][s]); red=F(pl['targets'][t]['reduction'][eff(t,s)])
                n+=R[t]*e*red
                if any(j[0]==t and j[2]<=s<j[3] for j in J): n-=R[t]*e*F(ex['disruption'])
            for ln in ex['links']:
                o=ln['owner']; n+=R[o]*F(c['exposure'][o][s])*F(ln['factor'])*min(F(pl['targets'][ln['left']]['reduction'][eff(ln['left'],s)]),F(pl['targets'][ln['right']]['reduction'][eff(ln['right'],s)]))
        nets.append(n)
    sv=[]
    for t in order:
        d=byt.get(t,{}); sv+=[d[1][2] if 1 in d else H+1, d[2][2] if 2 in d else H+1]
    res[tuple(sv)]=(nets,cr,pw)
print('count',len(res))
best=min(res.items(),key=lambda kv:(-min(kv[1][0]),-sum(kv[1][0]),kv[1][1],kv[1][2],kv[0]))
print('fixed',best[0],[float(x) for x in best[1][0]])
